dtsPropsFor.Button:
variant?: "primary" | "outline" | "ghost" | "link" | "checkout";
size?: "sm" | "md" | "lg" | "full";
children: React.ReactNode;
type?: "button" | "submit" | "reset";
disabled?: boolean;
className?: string;

dtsPropsFor.ButtonLink:
href: string;
variant?: "primary" | "outline" | "ghost" | "link" | "checkout";
size?: "sm" | "md" | "lg" | "full";
children: React.ReactNode;
className?: string;
target?: string;
rel?: string;

dtsPropsFor.Wordmark:
className?: string;
/** Use the cream artwork, for espresso and taupe surfaces. */
onDark?: boolean;
/** Horizontal is the default everywhere; stacked is for narrow or square space. */
variant?: "horizontal" | "stacked";
/** Rendered height in px; the lockup keeps its ratio. */
height?: number;

dtsPropsFor.Media:
image: { url: string | null; altText: string; width: number; height: number };
/** Responsive sizes string the layout uses; required for real images. */
sizes: string;
priority?: boolean;
className?: string;
/** Caption shown on the placeholder block. */
label?: string;

dtsPropsFor.ProductCard:
product: {
  id: string;
  handle: string;
  title: string;
  material: string;
  description: string;
  productType: string;
  featuredImage: { url: string | null; altText: string; width: number; height: number };
  priceRange: { minVariantPrice: { amount: string; currencyCode: "IDR" | "USD" } | null };
  options: { name: string; values: { name: string; available: boolean }[] }[];
  variants: { id: string; title: string; availableForSale: boolean; price: { amount: string; currencyCode: "IDR" | "USD" } | null }[];
  availableForSale: boolean;
};
sizes: string;
/** Set so the card's name never skips a heading level on the page it sits on. */
headingLevel?: "h2" | "h3";

dtsPropsFor.CatalogueFilters:
facets: { categories: string[]; sizes: string[] };
query: {
  categories: string[];
  sizes: string[];
  inStockOnly: boolean;
  sort: "featured" | "price-asc" | "price-desc";
};
/** Whether anything is currently narrowing the catalogue. */
filtered: boolean;
